import React, { useState } from "react";
import "../styles/Funds.css";
import Home from "../pages/Home";

const quickAmounts = [100, 250, 500, 1000, 2500, 5000];

function Funds() {
  const [amount, setAmount] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAmount = (value) => {
    setAmount(value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const numericAmount = Number(amount);

    if (!numericAmount || numericAmount < 10) {
      alert("Minimum amount is ₹10.");
      return;
    }

    if (numericAmount > 100000) {
      alert("Maximum amount is ₹100,000.");
      return;
    }

    try {
      setLoading(true);

      const token = localStorage.getItem("token");

      if (!token) {
        alert("Please login again.");
        return;
      }

      // Create Paytm transaction on your backend
      const response = await fetch(
        "http://localhost:5000/api/payments/create",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            amount: numericAmount,
            gateway: 'PAYTM'
          }),
        }
      );
      console.log("TOKEN EXISTS:", Boolean(token));

      const data = await response.json();

      console.log("STATUS:", response.status);
      console.log("DATA:", data);
      if (!response.ok || !data.success) {
        throw new Error(
          data.message || "Unable to create Paytm payment."
        );
      }

      /*
       * Expected backend response:
       *
       * {  
       *   success: true,
       *   paytm: {
       *     mid: "...",
       *     orderId: "...",
       *     txnToken: "...",
       *     amount: "500.00"
       *   }
       * }
       */

      if (
        !data.paytm ||
        !data.paytm.mid ||
        !data.paytm.orderId ||
        !data.paytm.txnToken
      ) {
        throw new Error(
          "Paytm transaction information is missing."
        );
      }

      // Make sure Paytm CheckoutJS is loaded
      if (
        !window.Paytm ||
        !window.Paytm.CheckoutJS
      ) {
        throw new Error(
          "Paytm Checkout is not loaded."
        );
      }

      const config = {
        root: "",

        flow: "DEFAULT",

        data: {
          orderId: data.paytm.orderId,
          token: data.paytm.txnToken,
          tokenType: "TXN_TOKEN",
          amount: data.paytm.amount,
        },

        merchant: {
          mid: data.paytm.mid,
          name: "RGBHAI SMM Panel",
          redirect: false,
        },

        handler: {
          notifyMerchant: function (
            eventName,
            eventData
          ) {
            console.log(
              "Paytm event:",
              eventName,
              eventData
            );
          },

          transactionStatus: function (
            paymentStatus
          ) {
            console.log(
              "Paytm transaction status:",
              paymentStatus
            );

            if (
              paymentStatus &&
              paymentStatus.STATUS ===
                "TXN_SUCCESS"
            ) {
              alert(
                "Payment successful. Verifying your payment..."
              );

              /*
               * IMPORTANT:
               * Do not add wallet balance here.
               *
               * Your backend should verify the
               * Paytm transaction and then credit
               * the wallet.
               */
            }

            if (
              paymentStatus &&
              paymentStatus.STATUS ===
                "TXN_FAILURE"
            ) {
              alert(
                paymentStatus.RESPMSG ||
                  "Payment failed."
              );
            }
          },
        },
      };

      // Initialize Paytm Checkout
      await window.Paytm.CheckoutJS.init(
        config
      );

      // Open Paytm
      window.Paytm.CheckoutJS.invoke();
    } catch (error) {
      console.error(
        "Paytm payment error:",
        error
      );

      alert(
        error.message ||
          "Unable to start Paytm payment."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="funds-page">
      <Home />

      <main className="funds-container">
        <div className="funds-heading">
          <h1>Add Funds</h1>

          <p>
            Add money to your account securely
            using Paytm.
          </p>
        </div>

        <div className="funds-layout">
          <div className="payment-card">
            <div className="payment-card-heading">
              <div className="wallet-icon">
                ₹
              </div>

              <div>
                <h2>Add Balance</h2>

                <p>
                  Enter the amount you want
                  to add.
                </p>
              </div>
            </div>

            <form onSubmit={handleSubmit}>
              <div className="fund-form-group">
                <label>Currency</label>

                <select
                  value="INR"
                  disabled
                >
                  <option value="INR">
                    INR - Indian Rupee ₹
                  </option>
                </select>
              </div>

              <div className="fund-form-group">
                <label>Amount</label>

                <div className="amount-input">
                  <span>₹</span>

                  <input
                    type="number"
                    value={amount}
                    onChange={(e) =>
                      handleAmount(
                        e.target.value
                      )
                    }
                    placeholder="Enter amount"
                    min="10"
                    max="100000"
                    step="1"
                  />
                </div>
              </div>

              <div className="quick-amounts">
                <label>
                  Quick Select
                </label>

                <div className="quick-buttons">
                  {quickAmounts.map(
                    (quickAmount) => (
                      <button
                        type="button"
                        key={quickAmount}
                        onClick={() =>
                          handleAmount(
                            quickAmount
                          )
                        }
                        className={
                          Number(amount) ===
                          quickAmount
                            ? "quick-btn selected"
                            : "quick-btn"
                        }
                      >
                        ₹{quickAmount}
                      </button>
                    )
                  )}
                </div>
              </div>

              <div className="payment-section">
                <label className="payment-label">
                  Payment Method
                </label>

                <div className="payment-methods">
                  <div className="payment-method selected">
                    <div className="method-icon">
                      ₹
                    </div>

                    <div className="method-content">
                      <strong>
                        Paytm
                      </strong>

                      <span>
                        Pay securely using
                        Paytm Checkout.
                      </span>
                    </div>

                    <div className="method-radio">
                      ✓
                    </div>
                  </div>
                </div>
              </div>

              <div className="payment-notice">
                <div className="notice-icon">
                  i
                </div>

                <p>
                  Your payment is processed
                  securely through Paytm.
                  Do not close the payment
                  window until the transaction
                  is completed.
                </p>
              </div>

              <button
                type="submit"
                className="add-money-button"
                disabled={loading}
              >
                {loading
                  ? "Creating Payment..."
                  : "Continue to Payment"}

                <span>→</span>
              </button>
            </form>
          </div>

          <aside className="funds-sidebar">
            <div className="current-balance-card">
              <div className="balance-card-top">
                <div>
                  <span>
                    Current Balance
                  </span>

                  <strong>
                    ₹0.00
                  </strong>
                </div>

                <div className="big-wallet">
                  ₹
                </div>
              </div>

              <div className="balance-line" />

              <p>
                Your available balance can
                be used to place new orders.
              </p>
            </div>

            <div className="fund-summary-card">
              <h3>
                Payment Summary
              </h3>

              <div className="fund-summary-row">
                <span>Amount</span>

                <strong>
                  {amount
                    ? `₹${Number(
                        amount
                      ).toFixed(2)}`
                    : "₹0.00"}
                </strong>
              </div>

              <div className="fund-summary-row">
                <span>
                  Payment Method
                </span>

                <strong>
                  Paytm
                </strong>
              </div>

              <div className="fund-summary-row">
                <span>
                  Processing Fee
                </span>

                <strong className="green">
                  Free
                </strong>
              </div>

              <div className="summary-separator" />

              <div className="fund-total">
                <span>Total</span>

                <strong>
                  {amount
                    ? `₹${Number(
                        amount
                      ).toFixed(2)}`
                    : "₹0.00"}
                </strong>
              </div>
            </div>

            <div className="fund-help-card">
              <div className="help-title">
                <div className="help-question">
                  ?
                </div>

                <h3>Need Help?</h3>
              </div>

              <p>
                Having trouble adding funds?
                Contact our support team.
              </p>

              <a href="/support">
                Contact Support →
              </a>
            </div>
          </aside>
        </div>
      </main>
    </div>
  );
}

export default Funds;
